<?php
require_once 'config/config.php';require_once 'includes/functions.php';require_login();
$filter=$_GET['status']??'all';$sql="SELECT l.*,b.title,m.name member_name,m.member_code FROM loans l JOIN books b ON b.id=l.book_id JOIN members m ON m.id=l.member_id";if($filter==='issued')$sql.=" WHERE l.status='Issued'";elseif($filter==='returned')$sql.=" WHERE l.status='Returned'";elseif($filter==='overdue')$sql.=" WHERE l.status='Issued' AND l.due_date<CURDATE()";$sql.=' ORDER BY l.id DESC';$rows=$pdo->query($sql)->fetchAll();
$summary=$pdo->query("SELECT COUNT(*) total, SUM(status='Issued') issued, SUM(status='Returned') returned, SUM(status='Issued' AND due_date<CURDATE()) overdue, COALESCE(SUM(fine_amount),0) fines FROM loans")->fetch();
$page_title='Reports';require 'includes/header.php';?>
<div class="page-heading"><div><p class="eyebrow">LIBRARY ANALYTICS</p><h1>Reports</h1><p class="muted">Circulation history, overdue books and collected fines.</p></div><button class="btn dark" onclick="window.print()">Print report</button></div>
<div class="stats-grid compact"><div class="stat-card"><span class="stat-label">Total transactions</span><strong><?=$summary['total']?></strong></div><div class="stat-card"><span class="stat-label">Currently issued</span><strong><?=$summary['issued']??0?></strong></div><div class="stat-card warning-stat"><span class="stat-label">Overdue</span><strong><?=$summary['overdue']??0?></strong></div><div class="stat-card"><span class="stat-label">Recorded fines</span><strong><?=money($summary['fines'])?></strong></div></div>
<section class="panel"><div class="panel-heading"><h2>Loan register</h2><div class="filters"><a class="<?=$filter==='all'?'active':''?>" href="reports.php">All</a><a class="<?=$filter==='issued'?'active':''?>" href="?status=issued">Issued</a><a class="<?=$filter==='overdue'?'active':''?>" href="?status=overdue">Overdue</a><a class="<?=$filter==='returned'?'active':''?>" href="?status=returned">Returned</a></div></div><div class="table-wrap"><table><thead><tr><th>Loan ID</th><th>Book</th><th>Member</th><th>Issue date</th><th>Due date</th><th>Return date</th><th>Fine</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):$over=$r['status']==='Issued'&&$r['due_date']<date('Y-m-d');?><tr><td>#<?=$r['id']?></td><td><?=e($r['title'])?></td><td><?=e($r['member_code'].' · '.$r['member_name'])?></td><td><?=e($r['issue_date'])?></td><td><?=e($r['due_date'])?></td><td><?=e($r['return_date']??'—')?></td><td><?=money($r['fine_amount'])?></td><td><span class="pill <?=$over?'red':($r['status']==='Returned'?'green':'blue')?>"><?=$over?'Overdue':e($r['status'])?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty">No transactions for this filter.</td></tr><?php endif;?></tbody></table></div></section>
<?php require 'includes/footer.php';?>
